import pandas as pd
from io import StringIO

def solve(data):
     total, count = 0.0, 0
     for chunk in pd.read_csv(StringIO(data['text']), chunksize=data['chunksize']):
         total += chunk['x'].sum()
         count += int(chunk['x'].count())
     return {'total':float(total), 'count':count, 'mean':float(total/count)}
